acing:.7px;cursor:pointer}.bottom-panel{grid-column:1/-1;display:grid;grid-template-columns:1fr 1.05fr;gap:0;min-height:140px}.log-wrap,.progress-wrap{padding:13px 17px}.log-wrap{border-right:1px solid var(--line)}.battle-log{height:83px;overflow:auto;margin-top:7px;font-size:10px;line-height:1.65;color:#a3b0a1}.log-entry{display:flex;gap:8px}.log-entry time{color:#758376;font-size:8px;min-width:37px}.log-entry em{font-style:normal;color:var(--green)}.region-list{display:flex;gap:6px;margin-top:9px}.region{flex:1;display:flex;align-items:center;gap:7px;min-width:0;background:#202a22;border:1px solid #303d31;padding:7px;border-radius:4px;color:#a5b0a3;text-align:left;cursor:pointer}.region.active{border-color:#71895e;background:#29382a;color:#ecf0e9}.region.locked{opacity:.46;cursor:not-allowed}.region-icon{font-size:15px;color:var(--green)}.region strong{font-size:8px;line-height:1.35;display:block;white-space:nowrap}.region small{font-size:7px;color:#829082;display:block;margin-top:2px}.region-count{font-size:9px;color:var(--green)}.bottom-buttons{display:flex;gap:7px;margin-top:8px}.subtle-btn{background:transparent;border:1px solid #354237;border-radius:3px;color:#9bab9b;padding:5px 8px;font-size:8px;letter-spacing:.7px;cursor:pointer}.subtle-btn:hover{color:var(--green);border-color:#708766}footer{height:32px;display:flex;align-items:center;justify-content:space-between;color:#667468;font-size:8px;letter-spacing:1px}.modal-backdrop{position:fixed;inset:0;z-index:10;background:#07100bd9;display:grid;place-items:center;padding:20px}.modal-backdrop.hidden{display:none}.modal{max-width:440px;width:100%;padding:28px;position:relative}.modal h2{font:25px 'Uncial Antiqua',serif;margin:13px 0}.modal p{color:#afbaac;font-size:12px;line-height:1.7}.modal-close{position:absolute;right:13px;top:10px;background:none;border:0;color:#aab5a8;font-size:22px;cursor:pointer}.confirm-btn{background:#526e46;border:1px solid #839b6a;color:white;padding:10px 15px;border-radius:3px;let