import * as THREE from 'three';

const $=id=>document.getElementById(id);
const regions=[
 {name:'Mossheart Glade',icon:'♧',foes:[['Mireling','WILD · LV 2',32,8,'slime'],['Briar Wolf','WILD · LV 3',46,10,'wolf'],['Rootbound Knight','ELITE · LV 4',72,13,'knight']]},
 {name:'Moonfen Crossing',icon:'☾',foes:[['Bog Wisp','WILD · LV 5',63,13,'wisp'],['Fen Stalker','WILD · LV 6',82,15,'wolf'],['Hollow Stag','ELITE · LV 7',125,18,'stag']]},
 {name:'Ashen Orchard',icon:'♨',foes:[['Cinderling','WILD · LV 8',98,17,'slime'],['Ashfang','WILD · LV 9',126,20,'wolf'],['The Pale Matron','ELITE · LV 10',185,25,'knight']]},
 {name:'Heartroot Sanctum',icon:'✧',foes:[['Veil Keeper','WILD · LV 12',155,23,'wisp'],['Elder Thorn','ELITE · LV 14',240,30,'stag'],['World-Eater Seed','MYTHIC · LV 16',360,36,'boss']]}
];
const initial={day:1,region:0,foe:0,level:1,xp:0,hp:100,mp:35,guard:false,wins:0,devoured:0,hero:'Rook',party:[{name:'Sable',role:'Thorn scout',icon:'⌁'},{name:'Nix',role:'Gloam wisp',icon:'✧'}]};
let state;try{state={...initial,...JSON.parse(localStorage.getItem('mawbound-save')||'{}')};state.party=JSON.parse(localStorage.getItem('mawbound-save')||'{}').party||initial.party}catch{state={...initial,party:[...initial.party]}}
let enemy,dead=false,busy=false,targetIndex=0,scene,camera,renderer,clock,heroMesh,enemyGroup,plants=[],fireflies,raycaster,mouse,orbit=false,ambientSound=false;
const color=new THREE.Color();const mat=(c,r=.82,m=0)=>new THREE.MeshStandardMaterial({color:c,roughness:r,metalness:m});
function makeShape(type, palette){
 const g=new THREE.Group(), add=(geo,m,x,y,z,sx=1,sy=1,sz=1)=>{const o=new THREE.Mesh(geo,m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;g.add(o);return o}, sphere=(m,x,y,z,sx,sy,sz)=>add(new THREE.SphereGeometry(1,18,14),m,x,y,z,sx,sy,sz), cyl=(m,r1,r2,h,x,y,z,seg=10)=>add(new THREE.CylinderGeometry(r1,r2,h,seg),m,x,y,z);
 if(type==='hero'){
  const cloak=mat('#394a38'), skin=mat('#d7ba98'), dark=mat('#24312a'), gold=mat('#c5a36d',.5,.4);
  sphere(cloak,0,1.08,0,.42,.56,.31);sphere(skin,0,1.72,0,.27,.3,.26);sphere(dark,0,1.79,-.08,.29,.19,.3);sphere(gold,0,1.6,.245,.2,.08,.04);cyl(cloak,.21,.3,.46,-.13,.37,0);cyl(cloak,.21,.3,.46,.13,.37,0);
  const blade=add(new THREE.ConeGeometry(.055,.9,6),gold,.52,.9,.03);blade.rotation.z=-.42;cyl(dark,.2,.2,.08,.52,.75,.03,8).rotation.z=1.15;
  sphere(mat('#91b47b',.5),-.12,1.92,.1,.035,.035,.035);
 }else if(type==='slime'){
  const body=mat('#91b66a',.35), shine=mat('#d2dfa1',.28), eye=mat('#292f26');sphere(body,0,.45,0,.49,.42,.43);sphere(body,0,.22,0,.42,.18,.38);sphere(shine,-.18,.59,.35,.08,.06,.025);sphere(eye,-.14,.47,.38,.045,.06,.025);sphere(eye,.14,.47,.38,.045,.06,.025);sphere(mat('#739457'),0,.96,0,.13,.25,.13);
 }else if(type==='wolf'||type==='stag'){
  const fur=mat(type==='wolf'?'#6c7770':'#887c5c'), cream=mat(type==='wolf'?'#c3c4a5':'#d7c58d'), eye=mat('#d6a467',.4,.15);
  sphere(fur,0,.78,0,.55,.3,.27);sphere(fur,.42,.97,.05,.27,.27,.24);sphere(cream,.58,.86,.08,.23,.12,.19);sphere(eye,.53,1.05,.252,.035,.04,.025);sphere(eye,.53,1.05,-.252,.035,.04,.025);
  for(const x of [-.3,.28])for(const z of [-.14,.15])cyl(fur,.09,.13,.52,x,.28,z,7);
  const ear=sphere(fur,.34,1.26,.08,.09,.22,.07);ear.rotation.z=-.32;sphere(fur,.51,1.26,-.08,.08,.2,.07);
  if(type==='stag'){const ant=mat('#d8c8a0');for(const s of [-1,1]){let a=cyl(ant,.025,.04,.48,.42,1.42,s*.14,5);a.rotation.z=s*.48;let b=cyl(ant,.018,.03,.28,.52,1.63,s*.23,5);b.rotation.z=-s*.4}}
 }else if(type==='wisp'){
  const core=mat('#83b7b0',.25,.25);core.emissive=new THREE.Color('#285d58');core.emissiveIntensity=1.4;sphere(core,0,.83,0,.37,.46,.32);sphere(mat('#d1ece0'),0,.87,.27,.2,.23,.1);sphere(mat('#192e2a'),-.1,.88,.36,.04,.065,.025);sphere(mat('#192e2a'),.1,.88,.36,.04,.065,.025);
  for(let i=0;i<4;i++){let t=sphere(core,Math.sin(i*2)*.34,.3+i*.3,-.08,.09,.18,.09);t.rotation.z=i*.6}
 }else if(type==='knight'||type==='boss'){
  const armor=mat(type==='boss'?'#594b51':'#596254',.48,.55), trim=mat('#c39b61',.45,.5), black=mat('#242b28');
  sphere(armor,0,1.16,0,.47,.57,.34);sphere(armor,0,1.88,0,.32,.38,.31);sphere(black,0,1.91,.28,.22,.14,.08);sphere(trim,0,1.83,.34,.12,.045,.02);
  for(const s of [-1,1]){sphere(armor,s*.44,1.38,0,.23,.25,.22);cyl(armor,.12,.18,.62,s*.19,.43,0,8)}
  const spike=add(new THREE.ConeGeometry(.085,.65,6),trim,.42,1.95,0);spike.rotation.z=-.42;
  for(let i=0;i<3;i++){let t=add(new THREE.ConeGeometry(.08,.38,5),trim,-.2+i*.2,2.1,0);t.rotation.z=.15}
 }
 return g;
}
function init3d(){
 const host=$('scene');scene=new THREE.Scene();scene.background=new THREE.Color('#17271f');scene.fog=new THREE.FogExp2('#17271f',.045);
 camera=new THREE.PerspectiveCamera(42,1,.1,100);camera.position.set(0,3.8,9.3);camera.lookAt(0,1,0);
 renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.18;host.appendChild(renderer.domElement);
 scene.add(new THREE.HemisphereLight('#cfdfce','#31402f',2));const moon=new THREE.DirectionalLight('#e4e6c6',3);moon.position.set(-4,8,5);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);scene.add(moon);const glow=new THREE.PointLight('#d1a96a',18,12);glow.position.set(0,2.3,-1.7);scene.add(glow);
 const floor=new THREE.Mesh(new THREE.CircleGeometry(16,60),mat('#334134'));floor.rotation.x=-Math.PI/2;floor.position.y=-.08;floor.receiveShadow=true;scene.add(floor);
 const ground=new THREE.Mesh(new THREE.PlaneGeometry(200,200),mat('#1b2b21'));ground.rotation.x=-Math.PI/2;ground.position.y=-.13;ground.receiveShadow=true;scene.add(ground);
 const bark=mat('#39473a'), leafMats=['#455d42','#526b46','#364d3c'].map(c=>mat(c));
 for(let i=0;i<24;i++){let x=(Math.random()-.5)*18,z=-2-Math.random()*12;if(Math.abs(x)<2.2&&z>-6)continue;let h=3+Math.random()*4;let trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13,.25,h,7),bark);trunk.position.set(x,h/2-.1,z);trunk.castShadow=true;scene.add(trunk);for(let n=0;n<3;n++){let crown=new THREE.Mesh(new THREE.IcosahedronGeometry(.8+Math.random()*.55,1),leafMats[Math.floor(Math.random()*3)]);crown.position.set(x+(Math.random()-.5)*.8,h*.68+n*.48,z);crown.scale.set(1,1.25,1);crown.castShadow=true;scene.add(crown)}}
 for(let i=0;i<22;i++){let x=(Math.random()-.5)*12,z=-.5-Math.random()*8;let m=mat(i%2?'#b98c67':'#d7a07d');let stem=new THREE.Mesh(new THREE.CylinderGeometry(.035,.045,.22,6),mat('#b4b28b'));stem.position.set(x,.04,z);scene.add(stem);let cap=new THREE.Mesh(new THREE.SphereGeometry(.12,10,7,0,Math.PI*2,0,Math.PI*.56),m);cap.position.set(x,.15,z);scene.add(cap)}
 plants=[];for(let i=0;i<45;i++){let p=new THREE.Mesh(new THREE.SphereGeometry(.025+Math.random()*.025,6,6),new THREE.MeshBasicMaterial({color:i%3?'#d4d890':'#9bc7a0'}));p.position.set((Math.random()-.5)*12,.3+Math.random()*4,-Math.random()*12);p.userData={phase:Math.random()*7,speed:.5+Math.random()};scene.add(p);plants.push(p)}
 heroMesh=makeShape('hero');heroMesh.position.set(-1.45,0,.4);scene.add(heroMesh);
 raycaster=new THREE.Raycaster();mouse=new THREE.Vector2();renderer.domElement.addEventListener('pointerdown',onSceneClick);window.addEventListener('resize',resize);resize();buildEnemy();animate();
}
function resize(){if(!renderer)return;const r=$('scene').getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/Math.max(1,r.height);camera.updateProjectionMatrix()}
function buildEnemy(){if(!scene)return;if(enemyGroup)scene.remove(enemyGroup);let kind=enemy.kind;enemyGroup=makeShape(kind);enemyGroup.position.set(1.45,0,-.1);enemyGroup.scale.setScalar(kind==='slime'?1.1:kind==='boss'?1.25:1);enemyGroup.traverse(o=>{if(o.isMesh){o.userData.foe=true}});scene.add(enemyGroup);$('enemy-name').textContent=enemy.name;$('enemy-caption').querySelector('.enemy-rank').textContent=enemy.rank;$('enemy-hp-text').textContent=`${enemy.hp} / ${enemy.max} VIT`;$('enemy-hp-bar').style.width='100%';$('target-label').textContent=enemy.name}
function animate(){requestAnimationFrame(animate);let t=clock?.getElapsedTime()??0;for(let i=0;i<plants.length;i++){let p=plants[i];p.position.y+=Math.sin(t*plants[i].userData.speed+plants[i].userData.phase)*.0008;p.material.opacity=.55+Math.sin(t*2+p.userData.phase)*.35;p.material.transparent=true}
 if(enemyGroup){enemyGroup.position.y=.045+Math.sin(t*2.2)*.045;enemyGroup.rotation.y=Math.sin(t*.7)*.09}if(heroMesh){heroMesh.position.y=Math.sin(t*1.8)*.018;if(busy)heroMesh.rotation.y=Math.sin(t*18)*.14;else heroMesh.rotation.y=Math.sin(t*.7)*.05}
 if(renderer)renderer.render(scene,camera)}
function onSceneClick(e){const rect=renderer.domElement.getBoundingClientRect();mouse.x=(e.clientX-rect.left)/rect.width*2-1;mouse.y=-(e.clientY-rect.top)/rect.height*2+1;raycaster.setFromCamera(mouse,camera);if(enemyGroup&&raycaster.intersectObject(enemyGroup,true).length){setTarget(0);toast('FOCUSED: '+enemy.name)}}
function setTarget(i){targetIndex=i;$('target-label').textContent=enemy.name}
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1000)}
function banner(msg){const b=$('combat-banner');b.textContent=msg;b.classList.add('show');clearTimeout(b.timer);b.timer=setTimeout(()=>b.classList.remove('show'),1400)}
function log(text){const box=$('battle-log'),row=document.createElement('div');row.className='log-entry';const tm=document.createElement('time');tm.textContent=`D${String(state.day).padStart(2,'0')}`;const msg=document.createElement('span');msg.innerHTML=text;row.append(tm,msg);box.prepend(row);while(box.children.length>15)box.lastChild.remove()}
function save(){try{localStorage.setItem('mawbound-save',JSON.stringify(state));$('save-state').textContent='● SAVED'}catch{$('save-state').textContent='● LOCAL'}}
function render(){const hp=Math.max(0,state.hp),mp=Math.max(0,state.mp);$('day-count').textContent=`DAY ${String(state.day).padStart(2,'0')}`;$('hero-name').textContent=state.hero;$('level-tag').textContent=`LV ${state.level}`;let xpNeed=40+(state.level-1)*25;$('xp-label').textContent=`${state.xp} / ${xpNeed}`;$('xp-bar').style.width=`${Math.min(100,state.xp/xpNeed*100)}%`;$('hero-hp-label').textContent=`${hp} / ${100+(state.level-1)*12}`;$('hero-hp-bar').style.width=`${hp/(100+(state.level-1)*12)*100}%`;$('hero-mp-label').textContent=`${mp} / ${35+(state.level-1)*4}`;$('hero-mp-bar').style.width=`${mp/(35+(state.level-1)*4)*100}%`;
 $('party-list').innerHTML=state.party.map(p=>`<div class="party-member"><span class="party-avatar">${p.icon}</span><span class="member-info"><strong>${p.name}</strong><small>${p.role}</small></span><span class="member-state">●</span></div>`).join('');
 $('region-list').innerHTML=regions.map((r,i)=>`<button class="region ${i===state.region?'active':''} ${i>state.region?'locked':''}" data-region="${i}" ${i>state.region?'disabled':''}><span class="region-icon">${r.icon}</span><span><strong>${r.name}</strong><small>${i<state.region?'CLEARED':i===state.region?'IN PROGRESS':'LOCKED'}</small></span></button>`).join('');$('region-count').textContent=`${String(state.region+1).padStart(2,'0')} / 04`;
 $('attack-btn').disabled=busy||dead;$('skill-btn').disabled=busy||dead||state.mp<12;$('guard-btn').disabled=busy||dead;$('feed-btn').disabled=busy||!dead;$('turn-status').textContent=dead?'◉ FOE DOWN':busy?'● FOE TURN':'● READY';$('turn-status').style.color=dead?'#d9b677':busy?'#df776d':'#a4d17c';save()}
function newEnemy(){let f=regions[state.region].foes[state.foe];enemy={name:f[0],rank:f[1],max:f[2]+(state.level-1)*2,hp:f[2]+(state.level-1)*2,atk:f[3]+Math.floor(state.region*2),kind:f[4]};dead=false;buildEnemy();render()}
function healParty(){state.hp=100+(state.level-1)*12;state.mp=35+(state.level-1)*4}
function playerAction(kind){if(busy||dead)return;if(kind==='skill'&&state.mp<12){toast('NOT ENOUGH ESSENCE');return}busy=true;render();let damage=kind==='skill'?Math.round(25+state.level*4+Math.random()*8):Math.round(11+state.level*3+Math.random()*6);if(kind==='skill')state.mp-=12;if(kind==='guard'){state.guard=true;state.mp=Math.min(35+(state.level-1)*4,state.mp+4);damage=0;log('<em>You brace for the coming blow.</em>');toast('GUARD RAISED');}else{enemy.hp=Math.max(0,enemy.hp-damage);log(`${kind==='skill'?'<em>Blood Bloom</em>':'You strike'} ${enemy.name} for <em>${damage} damage</em>.`);toast(`−${damage} VIT`);if(enemyGroup){enemyGroup.position.x+=.2;setTimeout(()=>{if(enemyGroup)enemyGroup.position.x=1.45},120)}$('enemy-hp-text').textContent=`${enemy.hp} / ${enemy.max} VIT`;$('enemy-hp-bar').style.width=`${enemy.hp/enemy.max*100}%`}
 if(enemy.hp<=0){dead=true;busy=false;state.wins++;state.xp+=18+state.region*7;log(`<em>${enemy.name} falls.</em> Its essence lingers...`);banner('THE WILD GROWS QUIET');render();return}
 setTimeout(()=>{if(state.guard){state.guard=false;log('Your ward turns aside the counterattack.');toast('BLOCKED')}else{let hit=Math.max(1,enemy.atk+Math.floor(Math.random()*5)-Math.floor((state.level-1)*1.5));state.hp=Math.max(0,state.hp-hit);log(`${enemy.name} lashes out for <em>${hit} damage</em>.`);toast(`−${hit} VIT`)}busy=false;if(state.hp<=0){state.hp=0;banner('DARKNESS TAKES YOU');log('<em>You collapse.</em> Rest at camp to rise again.')}render()},760)}
function devour(){if(!dead||busy)return;busy=true;let oldLv=state.level;state.devoured++;state.xp+=24+state.region*8;state.mp=Math.min(35+(state.level-1)*4,state.mp+8);log(`<em>You devour ${enemy.name}'s lingering essence.</em> +8 ESS.`);banner('ESSENCE ABSORBED');if(state.xp>=40+(state.level-1)*25){state.xp-=40+(state.level-1)*25;state.level++;state.hp+=24;state.mp+=8;log(`<em>LEVEL UP!</em> You are now level ${state.level}.`);toast(`LEVEL ${state.level}`)}if(state.party.length<4&&state.devoured%2===0){const names=[['Morrow','Mireling kin','♧'],['Vela','Fen wanderer','☾'],['Bramble','Root sentinel','✧']];let recruit=names[(state.devoured/2-1)%names.length];state.party.push({name:recruit[0],role:recruit[1],icon:recruit[2]});log(`<em>${recruit[0]} joins your coven.</em> A new bond is forged.`)}
 const list=regions[state.region].foes;if(state.foe<list.length-1)state.foe++;else if(state.region<regions.length-1){state.region++;state.foe=0;state.day++;log(`<em>New territory discovered: ${regions[state.region].name}.</em>`);$('scene-location').textContent=regions[state.region].name.toUpperCase();banner('THE PATH DESCENDS');}else{state.foe=0;state.day++;log('<em>The heartroot stirs again...</em> The wilds renew.')}newEnemy();busy=false;render()}
function camp(){if(busy)return;state.day++;healParty();dead=false;enemy.hp=enemy.max;log('<em>You make camp beneath the old boughs.</em> VIT and ESS restored.');toast('RESTED · FULLY RESTORED');$('enemy-hp-text').textContent=`${enemy.hp} / ${enemy.max} VIT`;$('enemy-hp-bar').style.width='100%';render()}
function setRegion(i){if(i>state.region)return;state.region=i;state.foe=0;state.day++;$('scene-location').textContent=regions[i].name.toUpperCase();newEnemy();log(`<em>You return to ${regions[i].name}.</em>`)}
function showModal(title,html){$('modal-title').textContent=title;$('modal-copy').innerHTML=html;$('modal').classList.remove('hidden')}
function init(){clock=new THREE.Clock();init3d();newEnemy();$('attack-btn').onclick=()=>playerAction('attack');$('skill-btn').onclick=()=>playerAction('skill');$('guard-btn').onclick=()=>playerAction('guard');$('feed-btn').onclick=devour;$('cycle-target').onclick=()=>setTarget((targetIndex+1)%1);$('rest-btn').onclick=camp;$('clear-log').onclick=()=>$('battle-log').replaceChildren();$('region-list').onclick=e=>{let b=e.target.closest('.region');if(b)setRegion(+b.dataset.region)};$('camera-btn').onclick=()=>{orbit=!orbit;camera.position.x=orbit?2.3:0;camera.lookAt(0,1,0);$('camera-btn').textContent=orbit?'◉  RESET VIEW':'◉  ORBIT VIEW'};
 $('reset-btn').onclick=()=>showModal('Begin again?',`<p>This erases your saved run and starts a fresh journey. This cannot be undone.</p><button class="confirm-btn" id="confirm-reset">ERASE SAVE & BEGIN</button>`);$('name-btn').onclick=()=>showModal('Choose a name',`<p>What should the hollow-born be called? Enter a name, then continue your journey.</p><input id="name-input" maxlength="14" value="${state.hero}" style="background:#202a22;color:#e9eee7;border:1px solid #53644f;padding:10px;border-radius:4px;width:100%;margin-bottom:10px"><button class="confirm-btn" id="save-name">SAVE NAME</button>`);
 $('party-info').onclick=()=>showModal('Your coven',`<p>Those changed by the wilds can choose to travel beside you. Devour a fallen foe to absorb a trace of its power. Every second absorbed essence may draw a new companion to your side.</p><p><b>${state.party.length} / 4 bonds forged</b> · ${state.devoured} essences absorbed</p>`);$('help-btn').onclick=()=>showModal('A strange second life',`<p><b>Strike</b> is a quick attack. <b>Blood Bloom</b> spends 12 essence for a heavy blow. <b>Brace</b> turns aside the next counterattack and restores a little essence.</p><p>When a foe falls, choose <b>Devour</b> to absorb its essence, gain experience, and advance deeper into the wilds. Camp to restore your vitality. Progress saves automatically in this browser.</p><p>This is an original dark-fantasy adventure with adult characters and non-explicit romance themes.</p>`);$('modal-close').onclick=()=>$('modal').classList.add('hidden');$('modal-ok').onclick=()=>$('modal').classList.add('hidden');$('modal').onclick=e=>{if(e.target.id==='modal')$('modal').classList.add('hidden')};$('modal').addEventListener('click',e=>{if(e.target.id==='confirm-reset'){localStorage.removeItem('mawbound-save');location.reload()}if(e.target.id==='save-name'){const v=$('name-input').value.trim();if(v)state.hero=v;save();$('modal').classList.add('hidden');render()}});window.addEventListener('keydown',e=>{if(e.target.tagName==='INPUT')return;if(e.key==='1')playerAction('attack');if(e.key==='2')playerAction('skill');if(e.key==='3')playerAction('guard');if(e.key==='4')devour()});log('<em>You awaken beneath a canopy of ancient roots.</em> The wilds are listening.');render()}
init();

