:700;color:#a8b5a7}.panel-kicker{display:flex;justify-content:space-between;align-items:center}.level-tag{color:var(--green);border:1px solid #394d38;padding:3px 6px;border-radius:3px;font-size:9px}.hero-row{display:flex;align-items:center;gap:11px;margin:11px 0 9px}.portrait{width:44px;height:44px;border-radius:5px;background:linear-gradient(145deg,#3e5443,#26372c);border:1px solid #52694f;display:grid;place-items:center;position:relative;color:#c5d994;font-size:29px}.portrait i{position:absolute;width:8px;height:8px;border-radius:50%;background:var(--green);right:-2px;bottom:-2px;border:2px solid #1b241e}.hero-ident{flex:1}.hero-ident h1{font:20px 'Uncial Antiqua',serif;margin:0 0 4px}.hero-ident p{font-size:8px;letter-spacing:1.2px;margin:0;color:var(--muted)}.hero-ident p span{color:var(--gold)}.tiny-more{border:0;background:none;color:#91a091;font-size:20px;cursor:pointer}.xp-row{display:flex;justify-content:space-between;color:#809080;font-size:8px;letter-spacing:1px;margin-bottom:5px}.xp-track,.vital-track{height:4px;background:#29342b;border-radius:5px;overflow:hidden}.xp-track i,.vital-track i{height:100%;display:block;background:var(--green);transition:width .3s}.vitals{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:12px}.vitals>div{position:relative;padding-left:17px}.vital-icon{position:absolute;left:0;top:0;font-size:11px}.vital-icon.hp{color:var(--red)}.vital-icon.mp{color:var(--blue)}.vital-label{font-size:8px;letter-spacing:1px;color:#aeb8ac}.vitals b{float:right;font-size:9px;color:#d4ddd1;font-weight:500}.vital-track{height:3px;margin-top:6px}.vital-track i{background:var(--red)}.vital-track.mana i{background:var(--blue)}.party-panel{padding:12px 15px}.section-heading{display:flex;justify-content:space-between;align-items:center}.text-action{border:0;background:transparent;color:var(--green);font-size:8px;letter-spacing:1px;cursor:pointer}.party-list{display:flex;gap:8px;margin-top:10px}.party-member{flex:1;min-width:0;background:#202a22;border:1px solid #334333;border-radius:4px;padding:7px 8px;display:flex;align-items:center;gap:7px}.party-avatar{width:28px;height:28px;border-radius:4px;display:grid;place-items:center;font-size:16px;background:#3a4631;color:#dfc28e}.party-member:nth-child(2) .party-avatar{background:#304044;color:#a6d0c9}.party-member:nth-child(3) .party-avatar{background:#4b3533;color:#e5a89a}.member-info{min-width:0;flex:1}.member-info strong{display:block;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.member-info small{color:#849184;font-size:8px}.member-state{color:var(--green);font-size:8px}.combat-panel{padding:12px 15px 11px;flex:1}.turn-mark{color:var(--green);font-size:8px;letter-spacing:1px}.action-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:10px}.action-card{position:relative;display:flex;align-items:center;text-align:left;gap:8px;background:#202a23;color:var(--text);border:1px solid #37453a;border-radius:4px;padding:8px;cursor:pointer;min-height:49px;transition:background .15s,border .15s,transform .15s}.action-card:hover{background:#29392b;border-color:#78906c;transform:translateY(-1px)}.action-card:disabled{opacity:.42;cursor:not-allowed;transform:none}.action-card.primary{border-color:#657d57;background:#283628}.act-icon{color:#e3c58f;font-size:17px;width:20px;text-align:center}.act-icon.skill{color:#d69b9e}.act-icon.guard{color:#9db6b2}.act-icon.feed{color:#a7cd7e}.action-card b{display:block;font-size:10px;font-weight:600}.action-card small{display:block;color:#9aa79a;font-size:8px;margin-top:3px;white-space:nowrap}.action-card kbd{position:absolute;right:6px;top:5px;font:8px 'DM Sans';color:#879387}.target-line{border-top:1px solid #2b382e;margin-top:9px;padding-top:8px;display:flex;align-items:center;gap:10px;font-size:8px;letter-spacing:1px;color:#839082}.target-line b{color:#e0e8dc;font-size:10px;letter-spacing:0;flex:1}.target-line button{border:0;background:none;color:var(--green);font-size:8px;letter-s